"""Kaggle GPU kernel: Voxtral-Mini-3B ASR run (self-contained).

The voxentity_eu package is embedded below (base64 zip) so the kernel does
not depend on a source dataset mount. Inputs come from the
voxentity-eu-inputs dataset; its audio directory may arrive zipped, which is
extracted here. Gold never enters this kernel.
"""

from __future__ import annotations

import base64
import io
import json
import subprocess
import sys
import zipfile
from pathlib import Path

PKG_B64 = ""

def _find_inputs() -> Path:
    for cand in (
        Path("/kaggle/input/datasets/gjusev/voxentity-eu-inputs"),
        Path("/kaggle/input/voxentity-eu-inputs"),
    ):
        if (cand / "inputs.jsonl").exists():
            return cand
    raise SystemExit(3)


INPUTS = _find_inputs()


def unpack_package() -> Path:
    work = Path("/kaggle/working/pkg")
    work.mkdir(parents=True, exist_ok=True)
    raw = base64.b64decode(PKG_B64)
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        z.extractall(work)
    for cand in (work / "src", work):
        if (cand / "voxentity_eu" / "__init__.py").exists():
            return cand
    raise SystemExit(3)


def ensure_audio_extracted() -> None:
    kinput = Path("/kaggle/input")
    print("kaggle/input:", sorted(p.name for p in kinput.iterdir()), flush=True)
    for d in sorted(kinput.iterdir()):
        if d.is_dir():
            print(" ", d.name, "->", sorted(x.name for x in d.iterdir())[:8], flush=True)
    if (INPUTS / "audio").is_dir() and any((INPUTS / "audio").iterdir()):
        return
    for zpath in INPUTS.glob("*.zip"):
        with zipfile.ZipFile(zpath) as z:
            z.extractall(INPUTS)


def main() -> int:
    subprocess.run(
        [sys.executable, "-m", "pip", "install", "-q",
         "pydantic>=2.7", "numpy", "scipy", "soundfile", "jiwer>=3.0",
         "transformers>=4.53", "accelerate", "librosa"],
        check=False,
    )
    pkg = unpack_package()
    print("package root:", pkg, flush=True)
    sys.path.insert(0, str(pkg))
    ensure_audio_extracted()
    import torch

    ok = torch.cuda.is_available()
    print("cuda:", ok, torch.cuda.get_device_name(0) if ok else "-", flush=True)
    from voxentity_eu.runner import run_asr

    result = run_asr(
        INPUTS,
        "voxtral-mini",
        Path("/kaggle/working/runs/voxtral-mini"),
        device="cuda:0" if ok else "cpu",
        dtype="bfloat16" if ok else "float32",
        resume=True,
    )
    print(json.dumps(result, indent=1))
    return 0 if result["failed"] < result["rows"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
